planning_identity.json.text:
{
  "title": "雨夜的温水",
  "theme_elements": [
    "雨夜归家的克制情绪表达",
    "温水作为母女间无需言说的情感连接载体",
    "代际之间的含蓄默契",
    "普通住宅餐厅的日常烟火质感"
  ],
  "story_arc": {
    "goal": "离家许久的成年女儿小安在雨夜回到家中，希望和久未顺畅沟通的母亲自然完成重聚，不刻意制造煽情场面",
    "stakes": "如果进门瞬间的生疏感没有被温柔打破，两人之间积攒的距离感会让这次归家变成尴尬的客套寒暄，失去重新靠近的柔软契机",
    "turning_point": "坐在餐桌旁的母亲看见站在门口犹豫的小安，没有起身快步相迎，只是默默将一杯提前晾好的温水放到桌边的空椅旁，用这个熟悉的日常小动作消解门口的局促",
    "resolution": "故事固定为雨夜母女重聚：成年女儿小安带行李回到家，在餐厅门口犹豫；母亲林阿姨看见她，将一杯温水放到桌边空椅旁；小安放下行李坐下，母亲将杯子推到她手边，小安接住杯子，最终两人安静地坐在同一张桌旁。"
  },
  "characters": [
    {
      "name": "AN",
      "description": "28岁左右成年女性，齐肩黑发带着被雨打湿的发梢，穿洗旧的卡其色风衣、深色直筒牛仔裤、白色帆布鞋，随身携带着黑色硬壳拉杆行李箱，神态带着久别归家的局促与犹豫，全程没有夸张的情绪外露",
      "mobility": "bipedal",
      "reference_mode": "identity"
    },
    {
      "name": "LIN_AUNT",
      "description": "58岁左右的母亲，鬓角有零星白发，穿藏青色针织开衫、浅灰色棉麻家居裤、布面居家拖鞋，神态平和克制，没有夸张的表情或动作，全程保持日常居家的松弛状态",
      "mobility": "bipedal",
      "reference_mode": "identity"
    }
  ],
  "scene_entities": [
    "black_hard_shell_suitcase",
    "transparent_warm_water_glass",
    "wooden_home_dining_table",
    "empty_dining_chair",
    "rain_streaked_dining_window"
  ],
  "locations": [
    {
      "id": "residential_dining_room",
      "description": "普通城市居民家的日常餐厅，空间紧凑，靠墙摆放着木质餐桌与配套餐椅，临窗位置可看到外面的雨夜街景，墙面为米白色乳胶漆，无华丽装饰，全片所有机位、局部取景均在该空间内，不切换其他物理地点"
    }
  ]
}

